import re
import string
from typing import Dict, Set, Tuple

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    """
    Parse a string in the described INI dialect and return a dictionary
    mapping section names to dictionaries of key/value pairs.
    """
    sections: Dict[str, Dict[str, str]] = {}
    current_section: str | None = None
    prev_key: str | None = None

    # regex for section headings
    section_regex = re.compile(r'^\s*\[([^\]]+)\]\s*$')

    def _add_section(name: str) -> Dict[str, str]:
        if name not in sections:
            sections[name] = {}
        return sections[name]

    # split a key/value line into key and value
    def _split_kv(line: str, lineno: int) -> Tuple[str, str]:
        pos_eq = line.find('=')
        pos_col = line.find(':')
        if pos_eq == -1 or (pos_col != -1 and pos_col < pos_eq):
            pos = pos_col
        else:
            pos = pos_eq
        if pos == -1:
            raise ValueError(f"Malformed line {lineno+1}: missing separator")
        key = line[:pos].strip()
        val_part = line[pos + 1 :].lstrip()

        # remove inline comment unless inside quotes
        in_quotes = False
        i = 0
        comment_start = None
        while i < len(val_part):
            ch = val_part[i]
            if ch == '"':
                in_quotes = not in_quotes
                i += 1
                continue
            if not in_quotes and ch in string.whitespace:
                if i + 1 < len(val_part) and val_part[i + 1] in ('#', ';'):
                    comment_start = i
                    break
            i += 1
        if comment_start is not None:
            val_part = val_part[:comment_start].rstrip()

        # quoted values keep inner text verbatim
        if val_part.startswith('"'):
            closing = None
            j = 1
            while j < len(val_part):
                if val_part[j] == '"':
                    closing = j
                    break
                j += 1
            if closing is None:
                raise ValueError(f"Unterminated quoted value at line {lineno+1}")
            value = val_part[1:closing]
        else:
            value = val_part
        return key, value

    for lineno, raw_line in enumerate(text.splitlines()):
        line = raw_line.rstrip('\n')
        stripped = line.strip()

        # skip empty or full-line comment lines
        if not stripped or stripped[0] in (';', '#'):
            continue

        # section header?
        m = section_regex.match(line)
        if m:
            current_section = m.group(1)
            _add_section(current_section)
            prev_key = None
            continue

        # continuation line (must follow a key line)
        if line[0].isspace():
            if prev_key is None:
                raise ValueError(f"Continuation line at line {lineno+1} without preceding key")
            prev_value = sections[current_section][prev_key]
            sections[current_section][prev_key] = prev_value + "\n" + line.strip()
            continue

        # must be a key/value line
        if current_section is None:
            raise ValueError(f"Key/value line outside any section at line {lineno+1}")
        key_raw, value = _split_kv(line, lineno)
        key = key_raw.lower()
        sections[current_section][key] = value
        prev_key = key

    # Separate DEFAULT section (which is not returned)
    defaults = sections.pop('DEFAULT', {})

    # Pre‑compute merged dictionaries (DEFAULT keys inherited)
    merged_sections: Dict[str, Dict[str, str]] = {}
    for sec_name, sec_vals in sections.items():
        merged = {}
        merged.update(defaults)      # inherited defaults
        merged.update(sec_vals)      # section overrides
        merged_sections[sec_name] = merged

    # Interpolation utilities
    placeholder_pattern = re.compile(r'\$\{([^}]+)\}')

    def _interpolate(
        sec_name: str,
        key: str,
        data: Dict[str, str],
        stack: Set[Tuple[str, str]],
    ) -> str:
        raw = data[key]
        if not isinstance(raw, str):
            return raw

        def replacer(match: re.Match[str]) -> str:
            token = match.group(1)
            if ':' in token:
                ref_sec, ref_key = token.split(':', 1)
            else:
                ref_sec, ref_key = sec_name, token
            ref_key = ref_key.lower()

            if ref_sec == 'DEFAULT':
                ref_data = defaults
            else:
                ref_data = merged_sections.get(ref_sec)
                if ref_data is None:
                    raise KeyError(f"Section {ref_sec!r} not found")
            if ref_key not in ref_data:
                raise KeyError(f"{ref_sec}:{ref_key!r} not found")

            if (ref_sec, ref_key) in stack:
                raise ValueError(f"Interpolation cycle detected for {ref_sec}:{ref_key}")

            return _interpolate(ref_sec, ref_key, ref_data, stack | {(ref_sec, ref_key)})

        result = raw
        while True:
            new, count = placeholder_pattern.subn(replacer, result)
            if count == 0:
                break
            result = new
        return result

    # Resolve all values and build final result
    result: Dict[str, Dict[str, str]] = {}
    for sec_name, sec_data in merged_sections.items():
        final_section: Dict[str, str] = {}
        for key in sec_data:
            final_section[key] = _interpolate(sec_name, key, sec_data, {(sec_name, key)})
        result[sec_name] = final_section

    return result
