from typing import List

def summarize_ranges(nums: List[int]) -> str:
    """Return a comma‑separated string summarizing consecutive runs."""
    if not nums:
        return ""

    sorted_nums = sorted(set(nums))
    parts = []

    start = sorted_nums[0]
    prev = sorted_nums[0]

    for num in sorted_nums[1:]:
        if num == prev + 1:
            prev = num
            continue

        # Close the current run
        run_len = prev - start + 1
        if run_len >= 3:
            parts.append(f"{start}..{prev}")
        else:
            parts.extend(str(n) for n in range(start, prev + 1))

        # Start a new run
        start = prev = num

    # Close the final run
    run_len = prev - start + 1
    if run_len >= 3:
        parts.append(f"{start}..{prev}")
    else:
        parts.extend(str(n) for n in range(start, prev + 1))

    return ",".join(parts)
